// Every external request is intercepted. Only 64 generated bytes are cached;
// no game, BIOS, live catalog or remote download is used by this regression.
import assert from 'node:assert/strict';
import { once } from 'node:events';
import puppeteer from 'puppeteer-core';
import { createServer } from '../scripts/server.mjs';

let mode = 'complete', upstreamCalls = 0, upstreamCanceled = false;
const fixture = Uint8Array.from({length: 64}, (_, i) => i);
const server = createServer({fetchArchive: async (_url, {signal}) => {
  upstreamCalls++;
  if (mode === 'waiting') return new Promise((_, reject) => {
    const abort = () => { upstreamCanceled = true; reject(signal.reason); };
    if (signal.aborted) abort(); else signal.addEventListener('abort', abort, {once: true});
  });
  return new Response(mode === 'short' ? fixture.slice(0, 16) : fixture);
}});
server.listen(0, '127.0.0.1'); await once(server, 'listening');
const base = `http://127.0.0.1:${server.address().port}`;
let browser;
try {
  browser = await puppeteer.launch({executablePath: process.env.CHROME_PATH || '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true, args: ['--no-sandbox']});
  const page = await browser.newPage(), errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.setRequestInterception(true);
  page.on('request', request => {
    const url = request.url();
    if (url === `${base}/archive-fixture.html`) return request.respond({status: 200, contentType: 'text/html',
      headers: {'cross-origin-opener-policy': 'same-origin', 'cross-origin-embedder-policy': 'require-corp'},
      body: '<!doctype html><title>Generated archive regression</title><body></body>'});
    if (url === 'https://archive.org/metadata/playstation-2-games-iso') return request.respond({status: 200, contentType: 'application/json', headers: {'access-control-allow-origin': '*'}, body: JSON.stringify({files: [{name: 'Generated fixture (USA).iso', size: '64'}]})});
    if (!url.startsWith(base + '/')) return request.abort('failed');
    request.continue();
  });
  await page.goto(`${base}/archive-fixture.html`);
  await page.evaluate(async () => {
    document.body.innerHTML = `<input id="archive-search"><select id="archive-region"><option value="all">All</option></select><select id="archive-sort"><option value="name">Name</option></select><button id="archive-refresh">Refresh</button><button id="archive-prev">Prev</button><button id="archive-next">Next</button><p id="archive-page"></p><ul id="archive-list"></ul><p id="archive-status"></p><progress id="archive-progress" hidden></progress><button id="archive-cancel" hidden>Cancel</button><input id="disc"><input id="bios">`;
    window.busyEvents = [];
    const {startArchive} = await import('./archive.js');
    startArchive(meta => {window.mounted = meta;}, () => false, value => {window.busyEvents.push(value);});
  });
  await page.waitForSelector('#archive-list button');
  const click = () => page.click('#archive-list button');
  const settled = () => page.waitForFunction(() => document.querySelector('#archive-cancel').hidden);
  const entries = () => page.evaluate(async () => {
    const dir = await (await navigator.storage.getDirectory()).getDirectoryHandle('pcsx2-library', {create: true});
    const names = []; for await (const name of dir.keys()) names.push(name); return names;
  });

  await click();
  await page.waitForFunction(() => document.querySelector('#archive-status').textContent.includes('cached and mounted'));
  assert.equal(upstreamCalls, 1);
  assert.deepEqual(await page.evaluate(async () => {
    const {getCachedFile} = await import('./storage.js');
    return [...new Uint8Array(await (await getCachedFile(window.mounted)).arrayBuffer())];
  }), [...fixture]);
  await page.evaluate(async () => {const {removeCachedFile} = await import('./storage.js'); await removeCachedFile(window.mounted); window.mounted = null;});

  mode = 'short';
  await click(); await settled();
  assert.match(await page.$eval('#archive-status', el => el.textContent), /Incomplete download: expected 64 bytes, received 16/);
  assert.deepEqual(await entries(), []);
  assert.equal(await page.evaluate(() => window.mounted), null);
  assert.equal(await page.$eval('#disc', el => el.disabled), false);
  assert.equal(await page.$eval('#archive-list button', el => el.disabled), false);

  mode = 'waiting';
  await click();
  await page.waitForFunction(() => !document.querySelector('#archive-cancel').hidden);
  // Wait until the mocked upstream has started before canceling it.
  for (let i = 0; upstreamCalls < 3 && i < 100; i++) await new Promise(resolve => setTimeout(resolve, 10));
  assert.equal(upstreamCalls, 3);
  await page.click('#archive-cancel'); await settled();
  assert.match(await page.$eval('#archive-status', el => el.textContent), /Download canceled/);
  for (let i = 0; !upstreamCanceled && i < 100; i++) await new Promise(resolve => setTimeout(resolve, 10));
  assert.equal(upstreamCanceled, true);
  assert.deepEqual(await entries(), []);
  assert.equal(await page.$eval('#bios', el => el.disabled), false);

  mode = 'complete';
  await click();
  await page.waitForFunction(() => document.querySelector('#archive-status').textContent.includes('cached and mounted'));
  assert.deepEqual(await page.evaluate(() => window.busyEvents), [true, false, true, false, true, false, true, false]);
  assert.deepEqual(errors, []);
  console.log('PASS: blocked direct fetch → local relay → generated OPFS cache; incomplete cleanup, cancellation, controls restored, retry succeeds. No remote downloads.');
} finally {
  await browser?.close(); server.closeAllConnections(); await new Promise(resolve => server.close(resolve));
}
